(4989520, 726421, 68256, '<td valign="top">Wow, this is such an awesome shot!  10 and a fav.  As a country boy this really connects me to the everyday life of a big city and makes me realize how much we have in common.</td>', 'Wow, this is such an awesome shot!  10 and a fav.  As a country boy this really connects me to the everyday life of a big city and makes me realize how much we have in common.', '2008-10-03 12:25:34.000000', NULL, 1),
(4989522, 724818, 68256, '<td valign="top">Strange that I like this...I''m not a fan of "crazy processing", but everthing about it works together to make the compostion appealing, from the wonderful browns to the balanced chaotic background.  10</td>', 'Strange that I like this...I''m not a fan of "crazy processing", but everthing about it works together to make the compostion appealing, from the wonderful browns to the balanced chaotic background.  10', '2008-10-03 12:29:05.000000', NULL, 1),
(4989524, 726807, 68256, '<td valign="top">I love the "chaotic balance" that you have created with this composition - specifically the shapes and angles.  It works amazingly well.</td>', 'I love the "chaotic balance" that you have created with this composition - specifically the shapes and angles.  It works amazingly well.', '2008-10-03 12:31:56.000000', NULL, 1),
(4989526, 727203, 68256, '<td valign="top">Looks like a Rangefinder Magazine senior portrait shot!  Great composition and processing.</td>', 'Looks like a Rangefinder Magazine senior portrait shot!  Great composition and processing.', '2008-10-03 12:33:56.000000', NULL, 1),
(4989528, 717225, 68256, '<td valign="top">I can''t imagine that this is doing very well here at DPC, but I really like the feeling and emotion that you''ve depicted  Great vision to make this work.</td>', 'I can''t imagine that this is doing very well here at DPC, but I really like the feeling and emotion that you''ve depicted  Great vision to make this work.', '2008-10-03 12:35:09.000000', NULL, 1),
(4989530, 726927, 68256, '<td valign="top">I''m amazed that you were able to get enough light on the inside of those doors.  Did you bounce a flash to fill in?  Anyway, it is a wonderful composition and great mood.  I wouldn''t change a thing.</td>', 'I''m amazed that you were able to get enough light on the inside of those doors.  Did you bounce a flash to fill in?  Anyway, it is a wonderful composition and great mood.  I wouldn''t change a thing.', '2008-10-03 12:38:00.000000', NULL, 1),
(4989531, 727065, 97166, '<td valign="top">It all happened on a balmy night in the summer of aught eight.  As the city slept peacefully, they were unaware of their impending doom.  One by one they gathered, one by one they joined their fellows, and one by one they eventually crept into the city and brought upon it the final doom.<br/> <br/>It was the Rise of the Sailboat.</td>', 'It all happened on a balmy night in the summer of aught eight.  As the city slept peacefully, they were unaware of their impending doom.  One by one they gathered, one by one they joined their fellows, and one by one they eventually crept into the city and brought upon it the final doom. It was the Rise of the Sailboat.', '2008-10-03 12:38:38.000000', NULL, 1),
(4989533, 727149, 97166, '<td valign="top">It... was just before dawn.<br/> <br/>It... Came out of nowhere.<br/> <br/>Its hunger was unsatiated, and none survived that day.  The day of the coming of the Creature of the Canal.</td>', 'It... was just before dawn. It... Came out of nowhere. Its hunger was unsatiated, and none survived that day.  The day of the coming of the Creature of the Canal.', '2008-10-03 12:39:46.000000', NULL, 1),
(4989535, 725374, 67152, '<td valign="top">a great find in the wild - i just wish the image were sharp and that the purple lens artifacts were not present</td>', 'a great find in the wild - i just wish the image were sharp and that the purple lens artifacts were not present', '2008-10-03 12:40:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4989536, 726722, 68256, '<td valign="top">Great purposed dynamic range.  Someday I hope to learn WHEN to use hdr because it works so well when done right (and looks aweful on 99% of my subjects).  Anyway, very nicely done.</td>', 'Great purposed dynamic range.  Someday I hope to learn WHEN to use hdr because it works so well when done right (and looks aweful on 99% of my subjects).  Anyway, very nicely done.', '2008-10-03 12:41:22.000000', NULL, 1),
(4989537, 727127, 97166, '<td valign="top">Sir Livingstone paused. A rustle in the bush to the left of the creek bed had startled him, but his breath returned as he saw the source moments later, a tapir coming out to drink. <br/> <br/>His breath then left him forever a moment later as the creature he didn''t hear took him from behind.  <br/> <br/>There''s a moral to this story. Never trust a Tapir.</td>', 'Sir Livingstone paused. A rustle in the bush to the left of the creek bed had startled him, but his breath returned as he saw the source moments later, a tapir coming out to drink.  His breath then left him forever a moment later as the creature he didn''t hear took him from behind.   There''s a moral to this story. Never trust a Tapir.', '2008-10-03 12:41:53.000000', NULL, 1),
(4989538, 724442, 67152, '<td valign="top">a majestic scene - the overly bright red roofs and the smoothed feel to the processing don''t work for me</td>', 'a majestic scene - the overly bright red roofs and the smoothed feel to the processing don''t work for me', '2008-10-03 12:42:03.000000', NULL, 1),
(4989541, 726116, 67152, '<td valign="top">beautiful streams of light - i just wish there were a subject to anchor the shot a bit more</td>', 'beautiful streams of light - i just wish there were a subject to anchor the shot a bit more', '2008-10-03 12:42:34.000000', NULL, 1),
(4989544, 725839, 67152, '<td valign="top">a gorgeous scene with the various shades of green and yellow - i just wish there were a main subject for us to anchor our view</td>', 'a gorgeous scene with the various shades of green and yellow - i just wish there were a main subject for us to anchor our view', '2008-10-03 12:44:11.000000', NULL, 1),
(4989545, 722557, 67152, '<td valign="top">Perfection</td>', 'Perfection', '2008-10-03 12:44:58.000000', NULL, 1),
(4989546, 725813, 97166, '<td valign="top">The mother bird shook her head sadly, and silently blamed it on the miserable winter of nesting that she''d had.  Her children would never get it.  It was a simple question. What is three plus three she''d ask? <br/> <br/>Of course, it didn''t occur to her that she didn''t even have six children.</td>', 'The mother bird shook her head sadly, and silently blamed it on the miserable winter of nesting that she''d had.  Her children would never get it.  It was a simple question. What is three plus three she''d ask?  Of course, it didn''t occur to her that she didn''t even have six children.', '2008-10-03 12:45:00.000000', NULL, 1),
