(4996232, 725729, 98219, '<td valign="top">Great shot</td>', 'Great shot', '2008-10-07 00:57:20.000000', NULL, 1),
(4996239, 725987, 97166, '<td valign="top">He ran, and ran, and ran.  It wasn''t real, it couldn''t be.  Another turn, another bush impeding him, another scratch from a thorn bush.  Panting, out of breath, Jack turned, and found the strength somehow to scream.  The truck was there still.  Beyond all reality, it was there, and it was coming for him.</td>', 'He ran, and ran, and ran.  It wasn''t real, it couldn''t be.  Another turn, another bush impeding him, another scratch from a thorn bush.  Panting, out of breath, Jack turned, and found the strength somehow to scream.  The truck was there still.  Beyond all reality, it was there, and it was coming for him.', '2008-10-07 01:02:41.000000', NULL, 1),
(4996307, 724145, 33672, '<td valign="top">This is more like art with a camera than most. I mean this in good way. 10</td>', 'This is more like art with a camera than most. I mean this in good way. 10', '2008-10-07 01:49:10.000000', NULL, 1),
(4996314, 726640, 33672, '<td valign="top">Great tonal range. You''ve really captured those earth tones.</td>', 'Great tonal range. You''ve really captured those earth tones.', '2008-10-07 01:52:56.000000', NULL, 1),
(4996318, 726722, 33672, '<td valign="top">Great composition and tones. Looks a bit HDR but that adds to the photo.10</td>', 'Great composition and tones. Looks a bit HDR but that adds to the photo.10', '2008-10-07 01:54:15.000000', NULL, 1),
