(4996590, 722048, 70661, '<td valign="top">Love the bone necklace! I wish you would win the blue with this! She''s so interesting! I really like the way you processed this too! 10</td>', 'Love the bone necklace! I wish you would win the blue with this! She''s so interesting! I really like the way you processed this too! 10', '2008-10-07 10:25:10.000000', NULL, 1),
(4996628, 721773, 70270, '<td valign="top">Great moment; love how the bee is almost entirely within the soft focus petal.  Soft focus works well here.</td>', 'Great moment; love how the bee is almost entirely within the soft focus petal.  Soft focus works well here.', '2008-10-07 10:48:52.000000', NULL, 1),
